use vstd::prelude::*;

verus! {
    fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
        requires
            a.len() <= u32::MAX as usize, // Ensure the length of the input vector is within bounds
        ensures
            result.len() == a.len() && // The output vector's length matches the input vector's length
            forall|i: nat| 0 <= i < result.len() ==> result[i] == 1 // All elements in the output vector are 1
    {
        let n = a.len() as nat; // Convert length to natural number
        let mut result = Vec::new(); // Initialize the output vector

        // Loop invariant:
        // 1. The loop counter `i` is within bounds (0 <= i <= n)
        // 2. The current output length equals the number of iterations completed
        // 3. All elements written so far are 1
        let mut i = 0;
        while i < n
            invariant
                0 <= i <= n, // Loop counter is within bounds
                result.len() == i as usize, // Current output length equals the number of iterations completed
                forall|j: nat| 0 <= j < i ==> result[j] == 1, // All elements written so far are 1
            decreases n - i // Decreases clause to ensure termination
        {
            result.push(1); // Append 1 to the result vector
            i = i + 1; // Increment the loop counter
        }

        // At the end of the loop, we have constructed the result vector
        // The loop invariant guarantees that result.len() == n and all elements are 1
        result
    }
}

